120	 */
121	u320_t uint320_mul(u320_t a, u320_t b)
122	{
123	    u320_t temp = {0};
124	
125	    // Schoolbook multiplication algorithm
126	    for (int32_t i = 0; i < 5; i+=1)
127	    {
128	        uint64_t carry = 0;
129	        for (int32_t j = 0; j < 5 - i; j+=1)
130	        {
131	            uint64_t high;
132	            uint64_t low;
133	            uint64_t product = a.limbs[i] * b.limbs[j];
134	            uint64_t old_value = temp.limbs[i + j];
135	
136	            // Add previous value and carry
137	            low = product + old_value;
138	            high = (low < product) ? 1 : 0;
139	            low += carry;
140	            high += (low < carry) ? 1 : 0;
141	
142	            temp.limbs[i + j] = low;
143	            carry = high;
144	        }
145	    }
