347	// FSM that uses compute iteratively to compute poly1305 MAC
348	typedef enum poly1305_state_t{
349	    // TODO can combine states for lower per block latency
350	    IDLE, // Wait for poly1305_key
351	    START_ITER, // Put data into compute
352	    FINISH_ITER, // Wait for data out of compute
353	    A_PLUS_S, // Add s to a final step before output
354	    OUTPUT_AUTH_TAG // Output the auth tag
355	} poly1305_state_t;
356	typedef struct poly1305_mac_fsm_t{
357	    uint1_t ready_for_key;
358	    uint1_t ready_for_data_in;
359	    stream(poly1305_auth_tag_uint_t) auth_tag;
360	    poly1305_mac_loop_body_in_t to_compute;
361	    uint1_t to_compute_valid;
362	    //uint1_t ready_for_from_compute;
363	}poly1305_mac_fsm_t;
364	poly1305_mac_fsm_t poly1305_mac_fsm(
365	    // Inputs
366	    stream(poly1305_key_uint_t) key,
367	    stream(axis128_t) data_in,
368	    uint1_t ready_for_auth_tag_out,
369	    u320_t from_compute,
370	    uint1_t from_compute_valid,
371	    uint1_t ready_for_to_compute
372	){
373	  poly1305_mac_fsm_t o;
374	  // Default not ready for incoming poly key
375	  o.ready_for_key = 0;
376	  // Default not ready for incoming data
377	  o.ready_for_data_in = 0;
378	  // Default not outputting an auth tag
379	  o.auth_tag.data = 0;
380	  o.auth_tag.valid = 0;
381	  // Default nothing into compute
382	  poly1305_mac_loop_body_in_t compute_null_inputs = {0};
383	  o.to_compute = compute_null_inputs;
384	  o.to_compute_valid = 0;
385	
386	  // The FSM
387	  static poly1305_state_t state;
388	  static uint1_t is_last_block;
389	  static u320_t a;
390	  static u320_t r;
391	  static u320_t s;
392	  if(state == IDLE){
393	    // Reset state
394	    is_last_block = 0; // Not the last block yet
395	    u320_t u320_null = {0};
396	    a = u320_null; // Initialize accumulator to 0
397	    r = u320_null; // Initialize r to 0
398	    s = u320_null; // Initialize s to 0
399	    // Wait for poly1305_key
400	    o.ready_for_key = 1;
401	    if(key.valid & o.ready_for_key){
402	      uint8_t poly1305_mac_data_key[POLY1305_KEY_SIZE];
403	      UINT_TO_BYTE_ARRAY(poly1305_mac_data_key, POLY1305_KEY_SIZE, key.data)
404	      // Key input
405	      u8_16_t r_bytes; // r part of the key
406	      u8_16_t s_bytes; // s part of the key
407	      // Split key into r and s 
408	      for(int32_t i=0; i<(POLY1305_KEY_SIZE/2); i+=1){
409	        r_bytes.bytes[i] = poly1305_mac_data_key[i];
