/* Code using a poly1305_mac_loop_body compute to evaluate: 
for (size_t i = 0; i < blocks; i++)
{
  // 'a' feeds back into the compute/next iteration
  a = poly1305_mac_loop_body(block_bytes, r, a);
}
*/
#include "uintN_t.h"
